update public.learning_paths
set
  title = 'Playwriting',
  goal = 'Playwriting',
  summary = 'A practical workshop in writing for the stage. Students study dramatic action, character, dialogue, structure, theatrical form, revision, and new-play development while drafting original scenes, a ten-minute play, and a revised one-act play. The course emphasizes writing for live bodies in space, rigorous peer response, dramaturgical curiosity, and the habits of a playwright working inside a collaborative theater culture.',
  data = $plywjson${"slug": "playwriting", "title": "Playwriting", "description": "A practical workshop in writing for the stage. Students study dramatic action, character, dialogue, structure, theatrical form, revision, and new-play development while drafting original scenes, a ten-minute play, and a revised one-act play. The course emphasizes writing for live bodies in space, rigorous peer response, dramaturgical curiosity, and the habits of a playwright working inside a collaborative theater culture.", "topics": [{"id": "28bac362-ce14-4575-a3d1-de8e972886bb", "type": "topic", "title": "The Impulse to Write", "description": "This opening unit helps students discover what makes a theatrical idea urgent, playable, and worth sustained attention.", "children": [{"id": "e662088c-3867-442f-b666-3a1309b7f3b8", "type": "subtopic", "title": "Personal obsessions and questions", "children": [{"id": "fcef5ef8-3396-457f-b0c5-c1c9b8ef85ba", "type": "concept", "title": "memory and observation"}, {"id": "1dab628a-fd71-44be-ae33-27a551b48006", "type": "concept", "title": "emotional stakes"}, {"id": "11887bc7-f620-40c1-b36e-fa4784d26f8d", "type": "concept", "title": "theatrical premises"}], "description": "Students learn to locate the images, conflicts, voices, and unanswered questions that can generate dramatic material."}, {"id": "78641900-a3e7-4c4f-bdb8-4a7a94c1f1cf", "type": "subtopic", "title": "Theater as a live medium", "children": [{"id": "9773643c-52db-43fd-b041-a4f60a45c85e", "type": "concept", "title": "liveness"}, {"id": "997c7a43-2368-4f1b-9896-9156ce23c414", "type": "concept", "title": "audience relationship"}, {"id": "387721f2-b893-4efe-8da1-e3b854c9144d", "type": "concept", "title": "embodied action"}], "description": "Students consider why an idea belongs on stage rather than in fiction, film, or essay form."}, {"id": "efaa9044-f57a-4188-a8da-dbcc7ac7a5f7", "type": "subtopic", "title": "Generating material", "children": [{"id": "15e49482-7694-4aa2-8e98-24371d8a9879", "type": "concept", "title": "freewriting"}, {"id": "81ce5121-7356-4982-b212-4adb4a980874", "type": "concept", "title": "image-based prompts"}, {"id": "4e85bbe5-bc1f-46fd-aaae-6fb166a1408f", "type": "concept", "title": "character monologues"}], "description": "Short writing prompts build fluency and reduce perfectionism at the start of the process."}]}, {"id": "f4592251-d3f1-4876-b2c2-9c93ba5acd25", "type": "topic", "title": "Dramatic Action and Conflict", "description": "Students learn that plays move through action: characters want things, make choices, meet resistance, and change the room.", "children": [{"id": "a9142dfd-3d55-429e-9c77-67af3bb48b2d", "type": "subtopic", "title": "Given circumstances and pressure", "children": [{"id": "eceaa661-5cfa-4a38-af8a-c6e95321458e", "type": "concept", "title": "stakes"}, {"id": "a9a44d2c-fe5b-4f50-8806-9224b1a6537b", "type": "concept", "title": "urgency"}, {"id": "5ab38793-efe6-4875-8899-e4c2951284c2", "type": "concept", "title": "constraints"}], "description": "The class studies how situation, time, place, and social pressure make behavior theatrically active."}, {"id": "a7cc0e81-4749-445f-899c-cb155635c3a2", "type": "subtopic", "title": "Objective, obstacle, tactic", "children": [{"id": "4d3b9127-74b7-4eef-ae46-ec4d9252f82f", "type": "concept", "title": "wants"}, {"id": "a36aaa96-413f-476b-a4d7-67a30dd0624a", "type": "concept", "title": "opposition"}, {"id": "c964d34d-76d5-4946-b343-02d7ac0cf8f0", "type": "concept", "title": "strategy shifts"}], "description": "Writers practice shaping scenes around playable wants rather than abstract themes."}, {"id": "bb09653a-888c-4f49-ba15-ba70c1242cfc", "type": "subtopic", "title": "Event and reversal", "children": [{"id": "1d0b1546-4e02-40d5-a17b-017fddc6d7fd", "type": "concept", "title": "turning points"}, {"id": "3c8bfb50-eb25-40ef-a906-c15077438642", "type": "concept", "title": "discoveries"}, {"id": "c07fd4a3-de75-4d51-be81-d1089e21c265", "type": "concept", "title": "power shifts"}], "description": "Students identify the moment a scene becomes irreversible and learn to write toward transformation."}]}, {"id": "86c6df44-7136-45a2-b189-bee24ff933c6", "type": "topic", "title": "Character and Dialogue", "description": "This unit develops characters as active presences whose speech reveals desire, history, rhythm, and contradiction.", "children": [{"id": "4a07159d-78ca-4f66-b326-a16fa98e29d6", "type": "subtopic", "title": "Character construction", "children": [{"id": "52b54881-6e2d-4c73-a824-9634553a8c7c", "type": "concept", "title": "status"}, {"id": "1441953e-7ba0-4905-8340-4d37c949e9b8", "type": "concept", "title": "contradiction"}, {"id": "897b1bac-a1e9-4bd3-9b4a-338668ede4d2", "type": "concept", "title": "backstory that affects action"}], "description": "Students build characters through behavior, relationships, social context, and theatrical need."}, {"id": "af69bb9a-3073-4c83-84bb-77203ac8aad3", "type": "subtopic", "title": "Dialogue as action", "children": [{"id": "39f59d04-20be-4566-9764-b2effcf61569", "type": "concept", "title": "subtext"}, {"id": "7fc27425-0038-414b-be44-31efd3116a28", "type": "concept", "title": "rhythm"}, {"id": "208c1807-0651-4302-b469-842f1ac44ce7", "type": "concept", "title": "interruption and silence"}], "description": "Students write dialogue that does something in the moment instead of merely explaining information."}, {"id": "4b614e9a-f22d-441d-b916-d3c2d0710dd4", "type": "subtopic", "title": "Voice and idiolect", "children": [{"id": "b51c50a1-d809-406f-8d68-69fb09d09435", "type": "concept", "title": "word choice"}, {"id": "498213b6-dd4c-47df-9e85-38d69beab107", "type": "concept", "title": "speech patterns"}, {"id": "f7ec7233-8559-4b99-aedb-571e85f937cd", "type": "concept", "title": "code-switching"}], "description": "The class examines how diction, syntax, pace, and metaphor create distinct dramatic voices."}]}, {"id": "66726a38-49ab-44de-ad18-31f5f1ae69f2", "type": "topic", "title": "Structure and Form", "description": "Students compare traditional and experimental structures so they can choose forms that serve the play's core experience.", "children": [{"id": "b098ddb4-8b4c-491f-99e7-bae9605ea3f1", "type": "subtopic", "title": "Scene architecture", "children": [{"id": "ea2692db-d458-4e27-b394-89565d49d307", "type": "concept", "title": "beats"}, {"id": "076c6342-196b-40fb-9f25-e9807d67b9cd", "type": "concept", "title": "escalation"}, {"id": "5517e04e-d6b6-42e3-9e6f-669217c5ec3c", "type": "concept", "title": "scene endings"}], "description": "Students learn how openings, beats, climaxes, and endings organize audience attention."}, {"id": "d369c36d-c705-4fbf-bfc7-debf8f18eb1a", "type": "subtopic", "title": "Act structure and alternatives", "children": [{"id": "d61bda0e-5047-4c9a-aa61-d13fd07f6de0", "type": "concept", "title": "arcs"}, {"id": "7f8612e2-8935-49e8-86a6-8df36417c203", "type": "concept", "title": "time jumps"}, {"id": "8052553d-b108-4893-834f-52170eba8a4b", "type": "concept", "title": "nonlinear design"}], "description": "The course compares one-act, two-act, episodic, circular, and fragmented forms."}, {"id": "313f2537-3886-4a19-ae5c-774ba68a4e47", "type": "subtopic", "title": "Genre and expectation", "children": [{"id": "3bfe3f0d-e5e9-47d6-8975-a393a92c506a", "type": "concept", "title": "genre conventions"}, {"id": "9d0cc59d-a392-4a0b-87cc-f19352771c69", "type": "concept", "title": "tonal control"}, {"id": "518a193c-a67d-4049-b25c-4bfec974a171", "type": "concept", "title": "hybrid forms"}], "description": "Students study how comedy, tragedy, realism, absurdism, documentary, and devised forms create different contracts with audiences."}]}, {"id": "4f127bb9-d59e-45dd-b727-b60bd3ce3679", "type": "topic", "title": "The Ten-Minute Play", "description": "The ten-minute play gives students a complete, high-pressure laboratory for premise, action, compression, and ending.", "children": [{"id": "9fef76e1-73c7-4886-81f7-04fc9a0f86b6", "type": "subtopic", "title": "Economy and premise", "children": [{"id": "512f0a03-1133-42a5-b049-44d4ed70fcb0", "type": "concept", "title": "compressed exposition"}, {"id": "e0021902-e001-4525-a798-21559c9938fd", "type": "concept", "title": "limited cast"}, {"id": "82430545-e922-4096-9d80-c72a89c28337", "type": "concept", "title": "single pressure point"}], "description": "Students practice beginning late, focusing the cast, and making one central event legible."}, {"id": "fa501997-6ae3-4b76-b08f-ec88113e42ea", "type": "subtopic", "title": "First draft workshop", "children": [{"id": "dde962af-e024-43b3-875e-a2ea9104759e", "type": "concept", "title": "draft deadlines"}, {"id": "fa0c8654-6d9d-4e3d-a7d9-ce3b3afb0258", "type": "concept", "title": "cold reads"}, {"id": "776776e2-7341-444b-b98b-e7049b0fed4d", "type": "concept", "title": "diagnostic questions"}], "description": "A short complete draft allows students to test action, voice, and structure quickly."}, {"id": "79ee3962-1c53-4e58-8a2c-898572c061a0", "type": "subtopic", "title": "Revision for performance", "children": [{"id": "a41398f4-3473-4dc3-a330-ebd3bfe6b811", "type": "concept", "title": "actable beats"}, {"id": "4c37443d-4f81-4563-95c3-f8a99020b2d4", "type": "concept", "title": "cuts"}, {"id": "5cd4d5de-f08b-4d20-9f29-016cb5bb012a", "type": "concept", "title": "ending image"}], "description": "Students revise with attention to actor clarity, staging practicality, and audience comprehension."}]}, {"id": "d62c57f6-2bc2-4c3c-a4fb-30cd4265a875", "type": "topic", "title": "Scene Writing", "description": "Scene work is the course's daily craft engine: students learn to make each exchange change the situation.", "children": [{"id": "860ec25f-0676-462c-b62d-748064fdf4d3", "type": "subtopic", "title": "Entrances, exits, and discoveries", "children": [{"id": "8e581ad2-25d5-44ec-80c9-5e7b62fd7181", "type": "concept", "title": "entrance events"}, {"id": "f26c1902-5162-4edb-9a68-eaeb877862cb", "type": "concept", "title": "new information"}, {"id": "22ece372-a2ea-4d37-aaca-9087e59bbd88", "type": "concept", "title": "exit pressure"}], "description": "Students learn how arrivals, departures, revelations, and withheld information create stage movement."}, {"id": "3b9a2be8-8a2f-49ab-b59d-6433bfa7fdaf", "type": "subtopic", "title": "Subtext and silence", "children": [{"id": "f21e2707-c6ef-4670-a3fd-80957f2c4dac", "type": "concept", "title": "pauses"}, {"id": "6d4d9e31-75c2-432f-9f9a-86458640aa9a", "type": "concept", "title": "avoidance"}, {"id": "12005120-64c1-4a54-ab4f-9f31347d566d", "type": "concept", "title": "double meaning"}], "description": "Students practice writing what characters avoid saying as carefully as what they say aloud."}, {"id": "17af9b82-cd20-45f6-acca-3554843c67d0", "type": "subtopic", "title": "Spatial and physical storytelling", "children": [{"id": "5a39d90f-d9bb-4870-9a3d-8653038db23d", "type": "concept", "title": "blocking potential"}, {"id": "51e5a09c-2e85-435e-a7ab-2c8d92350ff4", "type": "concept", "title": "props as action"}, {"id": "3b2309b9-1108-4fbf-a386-1c50d2f61c19", "type": "concept", "title": "visual rhythm"}], "description": "Scenes are revised for bodies, distance, props, and stage pictures, not just verbal exchange."}]}, {"id": "f7db1477-6651-4ef6-8e08-7018b2b2f57e", "type": "topic", "title": "Revision", "description": "Revision is framed as the playwright's central craft practice: a disciplined way to discover the stronger play inside the draft.", "children": [{"id": "1f875b85-d9d7-4c64-89a6-f29e5a2c3dbe", "type": "subtopic", "title": "Diagnostic reading", "children": [{"id": "ed6f7bb7-8501-459f-b939-433c1a49fa67", "type": "concept", "title": "event map"}, {"id": "52df2e7a-1572-4d39-b340-faf998359368", "type": "concept", "title": "character want audit"}, {"id": "fdd13e7b-4a68-4789-930c-fe05a22c031f", "type": "concept", "title": "audience questions"}], "description": "Students learn to identify the draft's central promise and the places where action stalls."}, {"id": "8d0b11ae-6d9e-4c80-a367-dc1011a840d2", "type": "subtopic", "title": "Structural rewriting", "children": [{"id": "923fe113-308f-44b7-8cd3-292fd76fdfa5", "type": "concept", "title": "cuts"}, {"id": "576f3f5d-d3f5-44bd-bc37-b9e85bcd84cb", "type": "concept", "title": "new scenes"}, {"id": "39959030-9b1b-48ad-b678-b5767f468e79", "type": "concept", "title": "reshaped openings"}], "description": "The class practices reordering, cutting, expanding, and reframing scenes to sharpen the whole play."}, {"id": "c7bae09b-a001-42a4-b760-d26009e87605", "type": "subtopic", "title": "Line-level revision", "children": [{"id": "53c3848b-b2f4-490a-a82b-e1718e76b346", "type": "concept", "title": "actable language"}, {"id": "ff338c53-f8bb-4ae4-85aa-7ba2c16c54d0", "type": "concept", "title": "clarity"}, {"id": "ea7a4b9e-b71f-4801-a5df-548758b5d8b1", "type": "concept", "title": "sound and pace"}], "description": "Students polish dialogue for specificity, compression, rhythm, and speakability."}]}, {"id": "3d85c6f5-d6b0-43bd-9784-fc9e3286a7c3", "type": "topic", "title": "Reading and Feedback", "description": "A strong workshop culture teaches writers to hear their work, ask useful questions, and respond to feedback without losing ownership.", "children": [{"id": "0a428d3b-58c8-4049-be4f-108fc296b357", "type": "subtopic", "title": "Workshop protocols", "children": [{"id": "f41a3703-b1b7-4af6-8aaa-50fb720a71a3", "type": "concept", "title": "Liz Lerman-style response"}, {"id": "60c2d107-b345-426c-87cb-633cd51f0563", "type": "concept", "title": "author questions"}, {"id": "32c3142d-f8e3-4086-afd9-c77e61bca5ca", "type": "concept", "title": "evidence-based notes"}], "description": "Students practice generous, specific, text-centered response methods."}, {"id": "8c573126-5e7a-4609-b34b-f839770e1b6a", "type": "subtopic", "title": "Hearing the play aloud", "children": [{"id": "a9d263bb-daa3-4d43-ba51-154eb68fc943", "type": "concept", "title": "table reads"}, {"id": "1045a05f-816f-43c8-a4ef-04ade4bf48eb", "type": "concept", "title": "casting for clarity"}, {"id": "dd7318de-be18-4c31-9d8b-da5b824675e5", "type": "concept", "title": "listening notes"}], "description": "Readings reveal pacing, confusion, repetition, theatrical images, and actor needs."}, {"id": "bf41f545-1d1f-4a0b-a7dd-f9a8999e6dd6", "type": "subtopic", "title": "Ethics of feedback", "children": [{"id": "f283e411-bd31-4314-9f2a-1e076c4f2542", "type": "concept", "title": "consent in discussion"}, {"id": "5621a8f5-f49b-4f09-91fd-d163d6f9570d", "type": "concept", "title": "harm reduction"}, {"id": "ee7fa76e-d602-4cdc-895f-56e384eec733", "type": "concept", "title": "specificity over assumption"}], "description": "Students learn to discuss identity, trauma, culture, and representation with rigor and care."}]}, {"id": "34b40aed-4808-4dea-83bb-4b283bcb3791", "type": "topic", "title": "Dramaturgy, Research, and Theatrical World", "description": "This unit strengthens student plays by connecting imagination to research, context, and stageable world-building.", "children": [{"id": "b49a9069-dc7d-4685-b2c5-a7294787aff3", "type": "subtopic", "title": "Research as generative practice", "children": [{"id": "80512459-8e16-4947-a8c1-706838203857", "type": "concept", "title": "archives"}, {"id": "4d98f2c4-5227-4e51-85f7-0f643ce2a2fb", "type": "concept", "title": "interviews"}, {"id": "abb7bb57-9f23-49a5-86cd-159c247abe97", "type": "concept", "title": "field observation"}], "description": "Students use research to complicate characters and situations rather than decorate the play."}, {"id": "84ba65c7-897e-450c-a474-66153b60ee9c", "type": "subtopic", "title": "Dramaturgical questions", "children": [{"id": "90435443-dd9f-4772-a98e-344f58b5d72c", "type": "concept", "title": "context packets"}, {"id": "82510fc0-2376-4f71-b351-cbe8a9c07583", "type": "concept", "title": "source ethics"}, {"id": "f32d256b-03ff-40a8-a826-573416d4c9eb", "type": "concept", "title": "audience assumptions"}], "description": "Students learn to ask what the play needs the audience to understand, feel, and question."}, {"id": "eea79a31-de34-406d-bcbf-945192af2d9b", "type": "subtopic", "title": "World of the play", "children": [{"id": "7b239ac4-ebce-4ecb-b0b5-4c734ab86d4a", "type": "concept", "title": "world rules"}, {"id": "1f4fd5f3-beaa-4140-b0d6-1b1f17eb92ba", "type": "concept", "title": "time systems"}, {"id": "855dd137-7f6e-4bae-a9c6-407a9a75565c", "type": "concept", "title": "public/private spaces"}], "description": "The unit clarifies rules of place, time, language, theatrical reality, and social order."}]}, {"id": "d22bc765-a11b-4a8d-a6de-247bbeb73c9f", "type": "topic", "title": "Theatricality, Space, and Collaboration", "description": "Playwriting becomes more advanced when students write for actors, designers, directors, space, and audience rather than for the page alone.", "children": [{"id": "dbbd3d1c-3fb9-4c3a-8683-26c505614ffb", "type": "subtopic", "title": "Writing for bodies and design", "children": [{"id": "8bafe5c3-ed3f-40c7-8d45-57d405d9c3fe", "type": "concept", "title": "stage directions"}, {"id": "00454608-515b-4b92-b32b-4f22af6fb9db", "type": "concept", "title": "design invitations"}, {"id": "99faf75b-c81d-4227-a207-7e9d7c50c24e", "type": "concept", "title": "sensory motifs"}], "description": "Students consider how light, sound, costume, objects, and movement carry meaning."}, {"id": "c93807a9-6c1e-46a8-9d80-91ca71d23fc4", "type": "subtopic", "title": "Collaboration with actors and directors", "children": [{"id": "59f87b6a-2120-4e5e-bed5-37b69e28d0e3", "type": "concept", "title": "rehearsal questions"}, {"id": "2af6b3af-2f57-4f5d-b89a-864b57031875", "type": "concept", "title": "rewrites in room"}, {"id": "c4801cfb-33b2-4c9b-b5d4-9fc178b7a93b", "type": "concept", "title": "collaborative boundaries"}], "description": "Students practice receiving performance discoveries without surrendering the play's central intention."}, {"id": "95ba02d0-c9b2-4957-851c-5b01dd1d7559", "type": "subtopic", "title": "Production feasibility", "children": [{"id": "138f822a-7e25-4209-a56a-16bfad80c4f7", "type": "concept", "title": "cast doubling"}, {"id": "72a0fdbe-70dc-45b7-9b04-1d0f7f41d7cc", "type": "concept", "title": "budget awareness"}, {"id": "b2708903-43ff-49b7-9666-c10c01bc51aa", "type": "concept", "title": "stage limitations"}], "description": "The class studies scale, cast size, technical needs, rights, and venue realities."}]}, {"id": "3153beeb-41c1-4087-bc00-2923fda0300d", "type": "topic", "title": "The One-Act Play", "description": "The one-act project asks students to sustain dramatic action over a longer arc while maintaining compression and theatrical focus.", "children": [{"id": "f579b6fc-d4e3-48d0-939c-68c65680c6b1", "type": "subtopic", "title": "Concept and outline", "children": [{"id": "927628c0-1f75-4360-a689-df50efb27c32", "type": "concept", "title": "logline"}, {"id": "448ab6a5-9ca0-4025-a013-1489c3af7811", "type": "concept", "title": "scene spine"}, {"id": "2d1fcd28-2a92-4072-a7b9-0b720423faeb", "type": "concept", "title": "character web"}], "description": "Students develop a premise, cast, world, and event sequence before drafting."}, {"id": "b07e0ea9-c817-4129-9956-ac9c685ea2d6", "type": "subtopic", "title": "Drafting the complete arc", "children": [{"id": "0857a021-0bd7-475f-a080-026b4050f5fa", "type": "concept", "title": "writing schedule"}, {"id": "6e2951b1-688c-4759-8089-e4485c9ae16d", "type": "concept", "title": "momentum"}, {"id": "b0cf4ad8-4370-4f94-9ff0-f26c0e6f646e", "type": "concept", "title": "midpoint pressure"}], "description": "The project emphasizes finishing a full draft, not only polishing isolated scenes."}, {"id": "eb4038cf-d598-429e-936b-8e77df035aff", "type": "subtopic", "title": "Revision portfolio", "children": [{"id": "1cdde67a-a58a-4d21-93bb-136917ac95a6", "type": "concept", "title": "revision memo"}, {"id": "85babcd1-4357-4c84-9354-50503fb6bc07", "type": "concept", "title": "before/after pages"}, {"id": "af9126df-6a9c-49a4-a5c6-d64a626a8f36", "type": "concept", "title": "process reflection"}], "description": "Students submit reflective notes and selected revisions to show craft growth."}]}, {"id": "39ecd62d-8429-49b4-9cc4-7c2882517784", "type": "topic", "title": "Staged Reading and New-Play Development", "description": "The capstone unit introduces professional development practices: rehearsal-room listening, rewrites, public presentation, and next steps.", "children": [{"id": "68c750f3-f772-46ec-af9f-a9a310306112", "type": "subtopic", "title": "Preparing the reading", "children": [{"id": "caccb278-77a9-4732-b5ab-d0452c87ae75", "type": "concept", "title": "script formatting"}, {"id": "4f1958e9-951a-4043-8745-a4e9ac16186c", "type": "concept", "title": "casting"}, {"id": "a558fd7c-6ba4-412a-9ef7-3218be1700fb", "type": "concept", "title": "reader packets"}], "description": "Students learn how to format scripts, cast readers, schedule rehearsal, and frame audience response."}, {"id": "1823e8ba-acdf-4b0f-ab2b-40773b2f59cb", "type": "subtopic", "title": "Development rehearsal", "children": [{"id": "d6ac96ae-a7c1-483f-aebf-f3d3f13173b2", "type": "concept", "title": "actor questions"}, {"id": "342ebfcd-7ba8-43ff-9ae7-29a6c785d6c9", "type": "concept", "title": "cuts during rehearsal"}, {"id": "69eef5c5-9d0b-409d-8e17-78c144891e2e", "type": "concept", "title": "playwright notes"}], "description": "The class treats rehearsal as a research tool for testing clarity, action, and theatrical life."}, {"id": "0f43531d-01ed-41ae-9f92-6cb41d6f2a64", "type": "subtopic", "title": "Public response and next steps", "children": [{"id": "0baa2378-7879-42ac-8cdc-b45184554f5b", "type": "concept", "title": "talkbacks"}, {"id": "e2b5f9cc-6bb3-48b4-b6ea-1e5ef10873f5", "type": "concept", "title": "submission strategy"}, {"id": "48a082ea-39fa-44f9-882c-e785aa4da3a6", "type": "concept", "title": "new-play networks"}], "description": "Students learn how to gather feedback, revise after presentation, and identify opportunities for continued development."}]}], "dbBacked": true}$plywjson$::jsonb,
